private static int Partition(int[] nums, int left, int right)
{
    int pivot = nums[right];      // last element as pivot
    int boundary = left;          // first position not yet known to be < pivot

    for (int i = left; i < right; i++)
    {
        if (nums[i] < pivot)
        {
            Swap(nums, i, boundary);
            boundary++;
        }
    }

    // Put the pivot between the two regions
    Swap(nums, boundary, right);
    return boundary;              // pivot's final index
}

public void QuickSort(int[] nums)
{
    var random = new Random();
    Sort(nums, 0, nums.Length - 1, random);
}

private static void Sort(int[] nums, int left, int right, Random random)
{
    if (left >= right) return;

    int pivotIndex = Partition(nums, left, right, random);

    Sort(nums, left, pivotIndex - 1, random);
    Sort(nums, pivotIndex + 1, right, random);
}

private static int Partition(int[] nums, int left, int right, Random random)
{
    // Move a random element to the end, then use it as the pivot
    int chosen = random.Next(left, right + 1);
    Swap(nums, chosen, right);

    int pivot = nums[right];
    int boundary = left;

    for (int i = left; i < right; i++)
    {
        if (nums[i] < pivot)
        {
            Swap(nums, i, boundary);
            boundary++;
        }
    }

    Swap(nums, boundary, right);
    return boundary;
}

private static void Swap(int[] a, int i, int j) => (a[i], a[j]) = (a[j], a[i]);

public void QuickSort(int[] nums)
{
    var random = new Random();
    Sort(nums, 0, nums.Length - 1, random);
}

private static void Sort(int[] nums, int left, int right, Random random)
{
    if (left >= right) return;

    int pivotIndex = Partition(nums, left, right, random);
    Sort(nums, left, pivotIndex - 1, random);
    Sort(nums, pivotIndex + 1, right, random);
}

private static int Partition(int[] nums, int left, int right, Random random)
{
    Swap(nums, random.Next(left, right + 1), right);
    int pivot = nums[right], boundary = left;

    for (int i = left; i < right; i++)
        if (nums[i] < pivot) Swap(nums, i, boundary++);

    Swap(nums, boundary, right);
    return boundary;
}

private static void Swap(int[] a, int i, int j) => (a[i], a[j]) = (a[j], a[i]);
